from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
links=set()
for p in r.pages:
    for a in p.get('/Annots',[]):
        o=a.get_object()
        act=o.get('/A',{})
        if hasattr(act, 'get'):
            u=act.get('/URI')
            if u:
                links.add(str(u))
for u in sorted(links):
    print(u)
